from __future__ import annotations

import gzip
import json
import os
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src"
sys.path.insert(0, str(SRC))

import genotype_txt_profile as gtp  # noqa: E402
import genotype_txt_tools as gtt  # noqa: E402
import genome_report_hotfix14 as gr14  # noqa: E402
import knowledge_enrichment as ke  # noqa: E402
import patient_input_profile as pip  # noqa: E402


def write_txt(path: Path) -> None:
    lines = [
        "# This data file generated by 23andMe at: synthetic",
        "# We are using reference human assembly build 37 (also known as Annotation Release 104).",
        "# rsid\tchromosome\tposition\tgenotype",
    ]
    for i in range(1, 31):
        gt = "AG" if i % 5 == 0 else "AA"
        lines.append(f"rs{i}\t1\t{i}\t{gt}")
    lines.extend(
        [
            "rs100\tX\t1\tA",
            "rs101\tY\t1\tG",
            "rs102\tMT\t1\tC",
            "rs103\t1\t31\tII",
            "rs104\t1\t32\tDI",
            "rs105\t1\t33\t--",
        ]
    )
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def write_array_vcf(path: Path) -> None:
    path.write_text(
        "##fileformat=VCFv4.2\n"
        "##source=Genotek\n"
        "##reference=hg19\n"
        "##FORMAT=<ID=GT,Number=1,Type=String,Description=Genotype>\n"
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tsample\n"
        "chr1\t100\trs1\tA\tG\t.\t.\t.\tGT\t0|0\n"
        "chr1\t200\trs2\tC\tT\t.\t.\t.\tGT\t0|1\n",
        encoding="utf-8",
    )


class GenotypeTxtProfileTests(unittest.TestCase):
    def test_txt_is_third_profile_without_reclassifying_core_unknown(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            patient = Path(directory)
            inp = patient / "input"
            inp.mkdir()
            write_txt(inp / "sample_normal.txt")
            core = pip.detect(patient)
            txt = gtp.detect(patient)
        self.assertEqual(core["kind"], pip.UNKNOWN_KIND)
        self.assertEqual(txt["kind"], gtp.KIND)
        self.assertEqual(txt["source"], "23andMe")
        self.assertEqual(txt["assembly"], "GRCh37")
        self.assertFalse(txt["capabilities"]["whole_genome_negative_evidence"])
        self.assertFalse(txt["capabilities"]["sequence_resolved_indels"])

    def test_existing_array_profile_remains_owned_by_core_detector(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            patient = Path(directory)
            inp = patient / "input"
            inp.mkdir()
            write_array_vcf(inp / "sample.vcf")
            core = pip.detect(patient)
            txt = gtp.detect(patient)
        self.assertEqual(core["kind"], pip.ARRAY_KIND)
        self.assertEqual(txt["kind"], gtp.UNKNOWN_KIND)

    def test_adapter_preserves_symbolic_calls_only_in_direct_export(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            source = root / "sample_normal.txt"
            source.write_text(
                "# This data file generated by 23andMe at: synthetic\n"
                "# We are using reference human assembly build 37 (also known as Annotation Release 104).\n"
                "# rsid\tchromosome\tposition\tgenotype\n"
                "rs1\t1\t1\tAA\n"
                "rs2\t1\t2\tCT\n"
                "i2\t1\t2\tCT\n"
                "rs3\t1\t3\tAA\n"
                "rs4\tX\t1\tT\n"
                "rs5\tX\t2\tA\n"
                "rs6\t1\t4\tII\n"
                "rs7\t1\t5\t--\n",
                encoding="utf-8",
            )
            fasta = root / "ref.fa"
            fai = root / "ref.fa.fai"
            gtt._write_test_fasta(fasta, fai)
            direct = root / "direct.txt.gz"
            gtt.export_23andme(source, direct, root / "direct_report.txt")
            with gzip.open(direct, "rt", encoding="utf-8") as handle:
                direct_text = handle.read()
            result = gtt.prepare_layers(
                source,
                fasta,
                fai,
                root / "snp.vcf.gz",
                root / "indel.vcf.gz",
                root / "residual.vcf.gz",
                root / "prep.txt",
            )
            with gzip.open(root / "snp.vcf.gz", "rt", encoding="utf-8") as handle:
                snp_text = handle.read()
        self.assertIn("rs6\t1\t4\tII", direct_text)
        self.assertIn("rs7\t1\t5\t--", direct_text)
        self.assertNotIn("rs6", snp_text)
        self.assertNotIn("rs7", snp_text)
        self.assertIn("rs5\tG\tA", snp_text)
        self.assertIn("\tGT\t1\n", snp_text)
        self.assertEqual(result["symbolic_indel_rows"], 1)
        self.assertEqual(result["duplicate_alias_rows_collapsed"], 1)

    def test_runtime_is_separate_and_hides_wgs_only_actions(self) -> None:
        source = (SRC / "genotype_txt_profile_runtime.ps1").read_text(encoding="utf-8-sig")
        menu = source.split("function Select-Mode", 1)[1]
        for item in ("3", "4", "5", "13", "14", "15", "16", "17", "18", "19", "27"):
            self.assertNotIn(f'Write-MenuItem "{item}"', menu)
        for item in ("1", "2", "6", "7", "8", "9", "10", "11", "12", "21", "22", "23", "24", "25", "26"):
            self.assertIn(f'Write-MenuItem "{item}"', menu)
        self.assertIn("GENOTYPE_TABLE_TXT", source)
        self.assertIn("DanteGenotypeTxtOriginalPrepareNormalizedLayers", source)
        self.assertIn("DanteGenotypeTxtOriginalRunFullVepAnnotation", source)
        self.assertIn("DanteGenotypeTxtOriginalSelectMode", source)
        self.assertIn('if (-not (Test-IsGenotypeTxtProfile))', source)
        self.assertIn('"--check-ref", "e"', source)

    def test_txt_stage24_confidence_is_not_array_or_wgs_confidence(self) -> None:
        event = ke.PatientEvent("SNV_INDEL", "v1", {"CATALOG"}, "1", 100, 100, ref="A", alt="G")
        old = os.environ.get("DANTE_INPUT_PROFILE_KIND")
        try:
            os.environ["DANTE_INPUT_PROFILE_KIND"] = "GENOTYPE_TABLE_TXT"
            confidence = ke.event_technical_confidence(event)
            self.assertTrue(confidence.startswith("GENOTYPE_TABLE_CALL_NO_READ_LEVEL_QC"))
            self.assertFalse(confidence.startswith("ARRAY_VENDOR_CALL"))
        finally:
            if old is None:
                os.environ.pop("DANTE_INPUT_PROFILE_KIND", None)
            else:
                os.environ["DANTE_INPUT_PROFILE_KIND"] = old

    def test_txt_report_scope_is_distinct_from_array_scope(self) -> None:
        state = {"input_profile": {"kind": "GENOTYPE_TABLE_TXT"}}
        self.assertTrue(gr14.is_txt_state(state))
        self.assertTrue(any("no-call" in line for line in gr14.TXT_COMMERCIAL_LEGAL))
        self.assertTrue(any("I/D" in line for line in gr14.TXT_COMMERCIAL_LEGAL))
        self.assertTrue(any("не отчет по полногеномному секвенированию" in line for line in gr14.TXT_COMMERCIAL_LEGAL))
        self.assertNotIn(15, gr14.TXT_STAGE_ITEMS)
        self.assertIn(24, gr14.TXT_STAGE_ITEMS)

    def test_deployment_manifest_tracks_txt_branch(self) -> None:
        manifest = json.loads((ROOT / "release" / "pipeline_manifest.json").read_text(encoding="utf-8"))
        for path in (
            "src/genotype_txt_profile.py",
            "src/genotype_txt_tools.py",
            "src/genotype_txt_profile_runtime.ps1",
            "src/knowledge_enrichment_hotfix8.py",
            "src/genome_report_hotfix14.py",
            "tests/test_genotype_txt_profile.py",
        ):
            self.assertIn(path, manifest["deployment_paths"])


if __name__ == "__main__":
    unittest.main()
